mapper.select:
SELECT * FROM (
  SELECT p.bsn_part_id,p.bsn_part_nm,s.ldr_nm,s.prft_dstrb_rt,s.bsn_fee_amt,s.aply_bgn_ym,
    (SELECT string_agg(h.aply_bgn_ym || ' ' || COALESCE(h.ldr_nm,'') || ' ' || h.prft_dstrb_rt || '% ' || h.bsn_fee_amt || '원', '; ' ORDER BY h.aply_bgn_ym)
      FROM mst.bsn_part_std_hist h WHERE h.bsn_part_id=p.bsn_part_id AND h.aply_bgn_ym > #{month}) AS "scheduledChanges",
    ,p.use_yn,p.sort_seq
  FROM mst.bsn_part p LEFT JOIN LATERAL (
    SELECT ldr_nm,prft_dstrb_rt,bsn_fee_amt,aply_bgn_ym FROM mst.bsn_part_std_hist h
    WHERE h.bsn_part_id=p.bsn_part_id AND h.aply_bgn_ym <= #{month} AND (h.aply_end_ym IS NULL OR h.aply_end_ym >= #{month})
    ORDER BY h.aply_bgn_ym DESC LIMIT 1
  ) s ON true
  WHERE p.bsn_part_id IN #{id}
) rows ORDER BY ${order}
